package cn.mop.api;

import cn.mop.domain.*;
import cn.mop.domain.assetmetadata.ManualAssetMetadata;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ManualAssetMetadataTest {
    static ManualAssetMetadata facts(String name,String type,String owner,String note){return new ManualAssetMetadata(name,type,"site-a-main",null,null,null,null,owner,null,null,null,null,null,note);}
    static Asset asset(String source,String lifecycle,String status,Instant sampled,String availability,String sync){Instant t=Instant.parse("2026-10-02T00:00:00Z");return new Asset("id","tenant","name","router","192.0.2.1","site-a-main",status,lifecycle,source,sampled,"unverified",1,t,t,availability,sync);}
    @Test void explicitUnknownsRemainNullAndTextIsNotSilentlyNormalized(){var value=facts("  明确保留名称  ","router",null,"  人工资料\n第二行\t  ");assertEquals("  明确保留名称  ",value.name());assertNull(value.brand());assertNull(value.ownerId());assertNull(value.purchaseDate());assertNull(value.collectionMethodNote());assertEquals("  人工资料\n第二行\t  ",value.note());}
    @Test void existingSixTypesOnlyAndOwnerUuidSyntaxDoesNotGrantMembership(){for(String type:List.of("router","switch","firewall","ap","wireless_controller","other"))assertDoesNotThrow(()->facts("name",type,null,"note"));for(String type:Arrays.asList(null,"","Router","server"))assertThrows(DomainException.class,()->facts("name",type,null,"note"));assertEquals("55000000-0000-4000-8000-0000000000ab",facts("name","router","55000000-0000-4000-8000-0000000000AB","note").ownerId());assertThrows(DomainException.class,()->facts("name","router","display name","note"));}
    @Test void requiredNoteAndNamesRejectBlankControlsSurrogatesAndTechnicalOverflow(){for(String value:Arrays.asList(null,"","\u00a0\ufeff","x\u0000","\ud800","x".repeat(101)))assertThrows(DomainException.class,()->facts(value,"router",null,"note"));for(String value:Arrays.asList(null,""," ","x\u0000","\ud800","😀".repeat(2001)))assertThrows(DomainException.class,()->facts("name","router",null,value));assertDoesNotThrow(()->facts("😀".repeat(100),"router",null,"😀".repeat(2000)));}
    @Test void optionalMetadataNeverConvertsBlankOrInvalidDatesToDefaults(){assertThrows(DomainException.class,()->new ManualAssetMetadata("n","router","site", " ",null,null,null,null,null,null,null,null,null,"note"));assertThrows(DomainException.class,()->new ManualAssetMetadata("n","router","site",null,null,null,"line\nlocation",null,null,null,null,null,null,"note"));assertNull(ManualAssetMetadata.parseDate(null));for(String value:List.of("","2026-02-29","2026/10/02","2026-10-02T00:00:00Z","0000-01-01","46000"))assertThrows(DomainException.class,()->ManualAssetMetadata.parseDate(value));assertEquals(LocalDate.of(2024,2,29),ManualAssetMetadata.parseDate("2024-02-29"));assertEquals(LocalDate.of(9999,12,31),ManualAssetMetadata.parseDate("9999-12-31"));}
    @Test void eligibilityRejectsImportedOrOnboardedAssetsWithoutInferringCmdbAuthority(){assertEquals(List.of(),ManualAssetMetadata.editBlockers(asset("manual","DRAFT","unknown",null,"UNKNOWN","PENDING_ONBOARDING")));for(String source:List.of("test_seed","cmdb","import"))assertTrue(ManualAssetMetadata.editBlockers(asset(source,"DRAFT","unknown",null,"UNKNOWN","PENDING_ONBOARDING")).contains("MANUAL_DRAFT_REQUIRED"));assertTrue(ManualAssetMetadata.editBlockers(asset("manual","ACTIVE","unknown",null,"UNKNOWN","PENDING_ONBOARDING")).contains("MANUAL_DRAFT_REQUIRED"));}
    @Test void anyMonitoringFactOrSyncProgressBlocksDraftMutation(){for(Asset value:List.of(asset("manual","DRAFT","ok",null,"UNKNOWN","PENDING_ONBOARDING"),asset("manual","DRAFT","unknown",Instant.now(),"UNKNOWN","PENDING_ONBOARDING"),asset("manual","DRAFT","unknown",null,"OK","PENDING_ONBOARDING"),asset("manual","DRAFT","unknown",null,"UNKNOWN","SYNCING")))assertTrue(ManualAssetMetadata.editBlockers(value).contains("MONITORING_STATE_NOT_PRISTINE"));assertEquals(List.of("ASSET_NOT_AVAILABLE"),ManualAssetMetadata.editBlockers(null));}
}
